-- DDL tương đương prisma/schema.prisma, dùng cho DB test cục bộ khi không chạy được `prisma db push`.
-- (Chỉ áp dụng cho DB test trống. Với DB thật hãy dùng `npx prisma db push`.)
DROP SCHEMA IF EXISTS public CASCADE; CREATE SCHEMA public;
CREATE TYPE "Role" AS ENUM ('ADMIN','STAFF','CUSTOMER');
CREATE TYPE "OrderStatus" AS ENUM ('PENDING','CONFIRMED','PROCESSING','SHIPPING','DELIVERED','CANCELLED','RETURNED');
CREATE TYPE "PaymentMethod" AS ENUM ('COD','VIETQR');
CREATE TYPE "PaymentStatus" AS ENUM ('UNPAID','PAID','REFUNDED');

CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"name" TEXT,"email" TEXT NOT NULL,"phone" TEXT,"passwordHash" TEXT,"role" "Role" NOT NULL DEFAULT 'CUSTOMER',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "User_phone_key" ON "User"("phone");
CREATE TABLE "Category" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"description" TEXT,"imageUrl" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "Category_slug_key" ON "Category"("slug");
CREATE TABLE "Product" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"shortDescription" TEXT NOT NULL,"description" TEXT NOT NULL,"ingredientsInci" TEXT NOT NULL,"usageGuide" TEXT NOT NULL,"storageGuide" TEXT,"skinTypes" TEXT[],"benefits" TEXT[],"images" TEXT[],"isFeatured" BOOLEAN NOT NULL DEFAULT false,"isActive" BOOLEAN NOT NULL DEFAULT true,"isCombo" BOOLEAN NOT NULL DEFAULT false,"categoryId" TEXT NOT NULL REFERENCES "Category"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "Product_slug_key" ON "Product"("slug");
CREATE TABLE "ProductVariant" ("id" TEXT PRIMARY KEY,"productId" TEXT NOT NULL REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE,"sku" TEXT NOT NULL,"name" TEXT NOT NULL,"price" INTEGER NOT NULL,"compareAtPrice" INTEGER,"weightGram" INTEGER NOT NULL DEFAULT 200,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "ProductVariant_sku_key" ON "ProductVariant"("sku");
CREATE TABLE "ComboItem" ("id" TEXT PRIMARY KEY,"comboProductId" TEXT NOT NULL REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE,"childVariantId" TEXT NOT NULL REFERENCES "ProductVariant"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"quantity" INTEGER NOT NULL DEFAULT 1);
CREATE TABLE "InventoryBatch" ("id" TEXT PRIMARY KEY,"variantId" TEXT NOT NULL REFERENCES "ProductVariant"("id") ON DELETE CASCADE ON UPDATE CASCADE,"batchCode" TEXT NOT NULL,"manufacturedDate" TIMESTAMP(3) NOT NULL,"expiryDate" TIMESTAMP(3) NOT NULL,"initialQuantity" INTEGER NOT NULL,"availableQuantity" INTEGER NOT NULL,"reservedQuantity" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "InventoryBatch_variantId_expiryDate_idx" ON "InventoryBatch"("variantId","expiryDate");
CREATE TABLE "Voucher" ("id" TEXT PRIMARY KEY,"code" TEXT NOT NULL,"description" TEXT,"discountType" TEXT NOT NULL,"discountValue" INTEGER NOT NULL,"minOrderAmount" INTEGER NOT NULL DEFAULT 0,"maxDiscount" INTEGER,"usageLimit" INTEGER,"usedCount" INTEGER NOT NULL DEFAULT 0,"startDate" TIMESTAMP(3) NOT NULL,"endDate" TIMESTAMP(3) NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true);
CREATE UNIQUE INDEX "Voucher_code_key" ON "Voucher"("code");
CREATE TABLE "Order" ("id" TEXT PRIMARY KEY,"orderCode" TEXT NOT NULL,"userId" TEXT REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE,"customerName" TEXT NOT NULL,"customerPhone" TEXT NOT NULL,"customerEmail" TEXT,"shippingAddress" TEXT NOT NULL,"province" TEXT NOT NULL,"district" TEXT NOT NULL,"ward" TEXT NOT NULL,"note" TEXT,"subtotal" INTEGER NOT NULL,"shippingFee" INTEGER NOT NULL,"discountAmount" INTEGER NOT NULL DEFAULT 0,"totalAmount" INTEGER NOT NULL,"voucherId" TEXT REFERENCES "Voucher"("id") ON DELETE SET NULL ON UPDATE CASCADE,"status" "OrderStatus" NOT NULL DEFAULT 'PENDING',"paymentMethod" "PaymentMethod" NOT NULL DEFAULT 'COD',"paymentStatus" "PaymentStatus" NOT NULL DEFAULT 'UNPAID',"paymentRef" TEXT,"trackingCode" TEXT,"shippingPartner" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "Order_orderCode_key" ON "Order"("orderCode");
CREATE TABLE "OrderItem" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE,"variantId" TEXT NOT NULL REFERENCES "ProductVariant"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"quantity" INTEGER NOT NULL,"unitPrice" INTEGER NOT NULL,"batchAllocated" JSONB);
CREATE TABLE "Review" ("id" TEXT PRIMARY KEY,"productId" TEXT NOT NULL REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE,"userId" TEXT REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE,"authorName" TEXT NOT NULL,"rating" INTEGER NOT NULL,"comment" TEXT NOT NULL,"images" TEXT[],"isApproved" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
